import React, { useEffect, useState } from "react";
import { Eye, EyeOff } from "lucide-react";
import { supabase } from "./supabaseClient.js";

// Shared password rules: at least 8 characters, one uppercase, one
// lowercase, one number. Returns an error string, or null if it passes.
export function validatePassword(pw) {
  if (!pw || pw.length < 8) return "Password needs to be at least 8 characters.";
  if (!/[A-Z]/.test(pw)) return "Password needs at least one uppercase letter.";
  if (!/[a-z]/.test(pw)) return "Password needs at least one lowercase letter.";
  if (!/[0-9]/.test(pw)) return "Password needs at least one number.";
  return null;
}

// A password input with a show/hide toggle — masked by default. Matches the
// plain-input styling used across the auth screens, so it drops in as a
// replacement for a bare <input type="password">.
export function PasswordField({ value, onChange, placeholder, autoComplete, required = true }) {
  const [visible, setVisible] = useState(false);
  return (
    <div style={{ position: "relative" }}>
      <input
        required={required}
        type={visible ? "text" : "password"}
        autoComplete={autoComplete}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        style={{ width: "100%", padding: "11px 44px 11px 12px", border: "1px solid #d8d8d8", borderRadius: 6, fontSize: 17, boxSizing: "border-box", fontFamily: "inherit" }}
      />
      <button
        type="button"
        onClick={() => setVisible((v) => !v)}
        aria-label={visible ? "Hide password" : "Show password"}
        style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: grey, display: "flex", alignItems: "center", padding: 4, cursor: "pointer" }}
      >
        {visible ? <EyeOff size={18} /> : <Eye size={18} />}
      </button>
    </div>
  );
}

// Shared brand tokens and small presentational atoms, ported from nbd_education_platform.jsx (the shell prototype).
// Real NBD brand colors: #a8cb63 (light green), #5e8f1e (deep green), #666666 (grey).
// Exact NBD brand colors, as supplied.
export const navy = { 50: "#f4f8ec", 100: "#e9f2d9", 300: "#c3e094", 500: "#a7cc63", 700: "#98cb63", 900: "#201b15" };
export const gold = "#98cb63";
export const cream = "#f8f8f8";
export const grey = "#666666";
export const WORDMARK_SRC = "data:image/png;base64,";
export const WORDMARK_WHITE_SRC = "data:image/png;base64,";
export const MARK_SRC = "data:image/png;base64,";
export const DEFAULT_HERO_BG_SRC = "data:image/jpeg;base64,";

export function Badge({ children, tone = "navy" }) {
  const tones = {
    navy: { background: navy[100], color: navy[700] },
    gold: { background: "#eef5e6", color: "#4d6b2c" },
    muted: { background: "#efe9e3", color: "#6b6155" },
  };
  return <span style={{ ...tones[tone], fontSize: 14, fontWeight: 500, padding: "3px 10px", borderRadius: 999 }}>{children}</span>;
}

export function StatCard({ label, value, icon: Icon }) {
  return (
    <div style={{ background: "#fff", border: "1px solid #e4dfd6", borderRadius: 12, padding: "16px 18px", flex: 1, minWidth: 140 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: "#8a8074", fontSize: 15, marginBottom: 8 }}>
        <Icon size={15} /> {label}
      </div>
      <div style={{ fontSize: 28, fontWeight: 600, color: navy[900] }}>{value}</div>
    </div>
  );
}

export function Logo({ size = 40 }) {
  return <img src={MARK_SRC} alt="National Beauty Distribution" style={{ height: size, width: "auto", display: "block", flexShrink: 0 }} />;
}

const DEFAULT_SITE_SETTINGS = {
  logo_url: null,
  logo_position_x: 50,
  logo_position_y: 50,
  logo_zoom: 1,
  background_url: null,
  background_position_x: 50,
  background_position_y: 50,
  background_zoom: 1,
  eyebrow: "National Beauty Distribution",
  headline: "Education Portal",
  subtitle: "Training, certification and brand education for our stockists",
  eyebrow_size: 15,
  headline_size: 42,
  subtitle_size: 15,
  content_x: 50,
  content_y: 50,
};

export function useSiteSettings() {
  const [settings, setSettings] = useState(null);
  const [loading, setLoading] = useState(true);

  async function reload() {
    const { data } = await supabase.from("site_settings").select("*").eq("id", 1).single();
    setSettings(data || DEFAULT_SITE_SETTINGS);
    setLoading(false);
  }

  useEffect(() => { reload(); }, []);

  return { settings: settings || DEFAULT_SITE_SETTINGS, loading, reload };
}

// Fixed stage height so brand-logo x/y percentages line up between this
// component and the drag-and-drop preview in Admin → Design.
export const HERO_STAGE_HEIGHT = "clamp(420px, 46vw, 520px)";

// The hero banner shown at the top of the sign-in and request-access
// screens. Everything here (logo, background, heading text, brand logo
// placement) is editable from Admin → Design — the form section below it
// is separate and fixed.
export function AuthHero() {
  const { settings } = useSiteSettings();
  const [brandLogos, setBrandLogos] = useState([]);
  const [bgReady, setBgReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    supabase
      .from("brands")
      .select("id,name,logo_url,hero_visible,hero_size,hero_x,hero_y")
      .not("logo_url", "is", null)
      .eq("hero_visible", true)
      .then(({ data }) => { if (!cancelled) setBrandLogos(data || []); });
    return () => { cancelled = true; };
  }, []);

  // Even embedded, a 2000x1370-ish JPEG still takes the browser a moment to
  // decode before it can paint as a background-image — without this, the
  // pale fallback colour shows first and the photo still pops in abruptly.
  // Decoding it explicitly via Image() and fading in once decoded turns
  // that pop into a smooth reveal, the same fix as before, just now keyed
  // off the embedded constant instead of a network fetch.
  useEffect(() => {
    let cancelled = false;
    const img = new Image();
    img.onload = () => { if (!cancelled) setBgReady(true); };
    img.src = DEFAULT_HERO_BG_SRC;
    if (img.complete) setBgReady(true);
    return () => { cancelled = true; };
  }, []);

  return (
    <div
      className="nbd-auth-hero"
      style={{
        background: navy[100],
        padding: "0 24px",
        position: "relative",
        height: HERO_STAGE_HEIGHT,
        overflow: "hidden",
      }}
    >
      {/* The hero photo is baked into the app itself (DEFAULT_HERO_BG_SRC)
          instead of being fetched from Storage on every page load — it loads
          with the rest of the page, with no network round-trip. Position/
          zoom still come from Design.
          background_zoom/position are tuned against a wide desktop viewport —
          sizing by a % of width alone can shrink the photo so much vertically
          on a narrow phone that it barely covers the banner. Forcing "cover"
          below the breakpoint guarantees the photo always fills the space,
          at the cost of the admin's exact zoom/position below that width. */}
      <style>{`@media (max-width: 700px) { .nbd-auth-hero-photo { background-size: cover !important; } }`}</style>
      {settings.background_url && (
        <div
          className="nbd-auth-hero-photo"
          style={{
            position: "absolute", inset: 0,
            backgroundImage: `url(${DEFAULT_HERO_BG_SRC})`,
            backgroundSize: `${settings.background_zoom * 100}%`,
            backgroundPosition: `${settings.background_position_x}% ${settings.background_position_y}%`,
            backgroundRepeat: "no-repeat",
            opacity: bgReady ? 1 : 0,
            transition: "opacity 400ms ease",
          }}
        />
      )}
      {settings.background_url && (
        <div style={{ position: "absolute", inset: 0, background: "rgba(255,255,255,0.55)" }} />
      )}

      {brandLogos.map((b) => (
        <img
          key={b.id}
          src={b.logo_url}
          alt={b.name}
          title={b.name}
          style={{
            position: "absolute",
            left: `${b.hero_x}%`,
            top: `${b.hero_y}%`,
            transform: "translate(-50%, -50%)",
            height: `${b.hero_size || 44}px`,
            maxWidth: 130,
            objectFit: "contain",
          }}
        />
      ))}

      <div
        style={{
          position: "absolute",
          left: `${settings.content_x ?? 50}%`,
          top: `${settings.content_y ?? 50}%`,
          transform: "translate(-50%, -50%)",
          width: "clamp(300px, 68vw, 620px)",
          textAlign: "center",
        }}
      >
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}>
          {settings.logo_url ? (
            <div style={{ background: "#fff", borderRadius: 16, padding: "clamp(16px, 2.4vw, 26px) clamp(28px, 5vw, 48px)", display: "inline-flex", overflow: "hidden", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
              <div style={{ height: "clamp(68px, 11vw, 130px)", width: "clamp(170px, 26vw, 300px)", overflow: "hidden", position: "relative" }}>
                <img
                  src={settings.logo_url}
                  alt="Logo"
                  style={{
                    position: "absolute",
                    inset: 0,
                    width: "100%",
                    height: "100%",
                    objectFit: "contain",
                    objectPosition: `${settings.logo_position_x}% ${settings.logo_position_y}%`,
                    transform: `scale(${settings.logo_zoom})`,
                  }}
                />
              </div>
            </div>
          ) : (
            <img src={WORDMARK_SRC} alt="National Beauty Distribution" style={{ height: "clamp(68px, 11vw, 130px)", display: "block" }} />
          )}
        </div>
        <div style={{ fontSize: settings.eyebrow_size || 15, fontWeight: 700, letterSpacing: 3, textTransform: "uppercase", color: navy[700], marginBottom: 6 }}>
          {settings.eyebrow}
        </div>
        <h1
          style={{
            fontFamily: "'Lato', -apple-system, sans-serif",
            fontWeight: 300,
            fontSize: `${settings.headline_size || 42}px`,
            color: navy[900],
            margin: "0 0 20px",
            lineHeight: 1.08,
          }}
        >
          {settings.headline}
        </h1>
        <div
          style={{
            fontSize: settings.subtitle_size || 15,
            letterSpacing: 2,
            textTransform: "uppercase",
            color: grey,
            maxWidth: 640,
            margin: "0 auto",
            lineHeight: 1.7,
          }}
        >
          {settings.subtitle}
        </div>
      </div>
    </div>
  );
}
